const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

(async () => {
  const htmlPath = process.argv[2];
  const outPath = process.argv[3];
  if (!htmlPath || !outPath) {
    console.error('Usage: node render_poster.js <input.html> <output.png>');
    process.exit(2);
  }

  const browser = await chromium.launch({ args: ['--font-render-hinting=medium'] });
  const page = await browser.newPage({ viewport: { width: 1080, height: 1520 }, deviceScaleFactor: 2 });

  // Use file:// URL.
  const url = 'file://' + path.resolve(htmlPath);
  await page.goto(url, { waitUntil: 'load' });
  await page.waitForTimeout(250);

  // Screenshot the poster container precisely.
  const poster = await page.locator('#poster');
  await poster.waitFor({ state: 'visible' });
  await poster.screenshot({ path: outPath, type: 'png' });

  await browser.close();
})();
